-- 0009: atribuição de vendedor aos contratos de agosto/2026 (fonte: Detalhe Comissão SGP)
-- Cria vendedoras faltantes e preenche vendedor_id. Idempotente. Não apaga nada.

insert into vendedores (nome, pop_id, ativo) select 'Jessica Valentim', p.id, true from pops p where p.nome='Altamira' and not exists (select 1 from vendedores v where v.nome='Jessica Valentim');
insert into vendedores (nome, pop_id, ativo) select 'Amanda Ribeiro', p.id, true from pops p where p.nome='Brasil Novo' and not exists (select 1 from vendedores v where v.nome='Amanda Ribeiro');
insert into vendedores (nome, pop_id, ativo) select 'Maclicya Martins', p.id, true from pops p where p.nome='Altamira' and not exists (select 1 from vendedores v where v.nome='Maclicya Martins');
insert into vendedores (nome, pop_id, ativo) select 'Aline Santos', p.id, true from pops p where p.nome='Brasil Novo' and not exists (select 1 from vendedores v where v.nome='Aline Santos');
insert into vendedores (nome, pop_id, ativo) select 'Loja VTX', p.id, true from pops p where p.nome='Vitória do Xingu' and not exists (select 1 from vendedores v where v.nome='Loja VTX');

update contratos set vendedor_id=(select id from vendedores where nome='Aline Santos') where sgp_contrato_id in ('22249');
